/// Aggregate metric values into a bounded summary.
pub struct Metrics {
    pub samples: Vec<f64>,
}

impl Metrics {
    pub fn mean(&self) -> f64 {
        if self.samples.is_empty() {
            return 0.0;
        }
        self.samples.iter().sum::<f64>() / self.samples.len() as f64
    }
}

/// Aggregate values into a single mean metric.
pub fn aggregate(values: &[f64]) -> f64 {
    if values.is_empty() {
        return 0.0;
    }
    values.iter().sum::<f64>() / values.len() as f64
}
